// GENERATED by docs/api/build-openapi-ts.mjs from docs/api/openapi.yaml — do not edit by hand.
export const OPENAPI_YAML = "openapi: 3.1.0\ninfo:\n  title: Covva API\n  version: 1.0.0\n  summary: REST API for the Covva mobile app and partner (broker/insurer) integrations.\n  description: |\n    Covva is a **technology platform**. It is not an insurer or broker, does not\n    give advice in its own name and never holds premiums. Every response that concerns a\n    transaction carries the information needed to show the mandatory disclosure.\n\n    ## Authentication\n    * **Customer / partner users** — `Authorization: Bearer <Supabase access token>` (mobile) or the\n      Supabase session cookie (web). Requests run as that user, so Postgres Row Level Security applies.\n    * **Partner integrations** — `x-api-key: imk_<prefix>_<secret>` (see `/partner/*`). Keys belong to a\n      broker or insurer organisation and carry scopes: `requests:read`, `quotes:write`,\n      `policies:issue`, `claims:write` (or `*`).\n\n    ## Envelope\n    Every JSON response (except the AI chat stream and redirects) is an `ApiResult`:\n    `{ \"ok\": true, \"data\": … }` or `{ \"ok\": false, \"error\": { \"code\", \"message\", \"details?\" } }`.\n\n    | HTTP | `error.code` | Meaning |\n    |---|---|---|\n    | 400 | `invalid_input` | Validation failed (`details` lists `{ path, message }`) |\n    | 401 | `unauthorised` | Missing/expired token or invalid API key |\n    | 403 | `forbidden` | Authenticated but not allowed |\n    | 404 | `not_found` | Not found or not visible to you |\n    | 409 | `conflict` | Duplicate / already done |\n    | 422 | `business_rule` | A product rule blocked it (e.g. quote expired, broker not disclosed). Show `message` to the user. |\n    | 429 | `rate_limited` | Slow down; see `Retry-After` |\n    | 503 | `unavailable` | Feature switched off or not configured (AI, payments) |\n    | 500 | `internal_error` | Unexpected error; quote `x-request-id` to support |\n\n    Every response has an `x-request-id` header (send your own to correlate).\n\n    ## Product rules clients must honour\n    * Show the broker-of-record disclosure and record it (`POST /requests/{id}/disclosure`) **before** an application.\n    * Only `ready_to_accept` quotes can be applied for, and only before `valid_until`.\n    * Payment confirmation never activates cover. Show cover as active only when `policy.status = active`.\n    * Reporting a claim is not approval. Only the insurer decides claims.\n    * When `demoMode` is true, show \"Illustrative only · Demo data\" near insurer names and prices.\n    * AI output is labelled as AI-assisted and is never a suitability or claim decision.\n  contact:\n    name: Platform engineering\n    email: support@covva.com.gh\nservers:\n  - url: https://{host}/api/v1\n    variables:\n      host:\n        default: covva.com.gh\n  - url: http://localhost:3000/api/v1\nsecurity:\n  - bearerAuth: []\ntags:\n  - name: Webhooks\n    description: |\n      Signed HTTP callbacks to partner endpoints (configured in Team settings → Developer). Every delivery is a\n      `POST` with headers `x-covva-event`, `x-covva-delivery`, `x-covva-timestamp` and `x-covva-signature`\n      (`HMAC-SHA256(endpoint secret, \"{timestamp}.{raw body}\")`, hex). Respond 2xx within 10 s; failures retry after\n      1 min, 5 min, 30 min, 2 h and 12 h. Payloads carry ids, references, statuses, amounts and dates only — never\n      personal data; fetch details through the API. See `docs/WEBHOOKS.md`.\n  - name: Me\n  - name: Catalogue\n  - name: Requests\n  - name: Documents\n  - name: Applications & payments\n  - name: Policies\n  - name: Claims\n  - name: Complaints\n  - name: Notifications & devices\n  - name: AI\n  - name: Partner API\n  - name: System\n\npaths:\n  /me:\n    get:\n      tags: [Me]\n      summary: Current user — profile, memberships, feature flags, consent state\n      responses:\n        \"200\": { $ref: \"#/components/responses/Me\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n    patch:\n      tags: [Me]\n      summary: Update own profile\n      description: KYC status can't be changed by the client (enforced in the database).\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdateProfileInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /me/consents:\n    post:\n      tags: [Me]\n      summary: Record consent decisions (append-only)\n      description: When `version` is omitted the current `terms_version` / `privacy_version` is used.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RecordConsentsInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /catalog/categories:\n    get:\n      tags: [Catalogue]\n      summary: Insurance categories with availability and `risk_schema` (form definition)\n      security: []\n      responses:\n        \"200\":\n          description: Categories\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { type: array, items: { $ref: \"#/components/schemas/Category\" } } }\n  /catalog/categories/{slug}:\n    get:\n      tags: [Catalogue]\n      summary: One category with approved products from participating insurers\n      security: []\n      parameters: [{ name: slug, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /catalog/insurers:\n    get:\n      tags: [Catalogue]\n      summary: Public directory of active insurers and brokers (for \"add a policy bought elsewhere\")\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /needs-assessment:\n    get:\n      tags: [Catalogue]\n      summary: The \"help me choose\" questions\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Catalogue]\n      summary: Run the needs assessment and store the answers\n      description: Works signed-in (bearer) or anonymously (pass `anonymousId`). Returns categories to consider — not product advice.\n      security: [{}, { bearerAuth: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/NeedsAssessmentInput\" } } }\n      responses:\n        \"200\":\n          description: Suggestions\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/NeedsResult\" } }\n\n  /requests:\n    get:\n      tags: [Requests]\n      summary: The customer's requests\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: open, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Create (and by default submit) a request\n      description: |\n        Validates `risk` against the category's `risk_schema`, routes exactly one broker of record,\n        prices estimates from approved rating rules and creates document tasks. `source` is recorded as `mobile`.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateRequestInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}:\n    get:\n      tags: [Requests]\n      summary: Request detail — customer-visible timeline, tasks, broker, documents, applications, payments, policies\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/cancel:\n    post:\n      tags: [Requests]\n      summary: Cancel an open request (customer)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/quotes:\n    get:\n      tags: [Requests]\n      summary: Quotes, comparison result and disclosure text\n      description: |\n        `comparison` is the engine output (`insurersCompared`, `productsCompared`, `criteria`, `ranked`, `paidPlacements`,\n        `materialExclusions`, `disclaimer`). Show `summary` (e.g. \"3 quotes from 3 participating insurers compared\"),\n        each quote's `statusLabel`, `labels` (explained, never an unexplained \"best\"), `valid_until` and `comparedAt`.\n        Paid placements are listed separately and never ranked.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\":\n          description: Quotes\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/QuotesResult\" } }\n  /requests/{id}/disclosure:\n    post:\n      tags: [Requests]\n      summary: Acknowledge the broker-of-record disclosure (required before applying). Idempotent.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/DisclosureAckInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/messages:\n    get:\n      tags: [Requests]\n      summary: Message thread with the broker (oldest first within the page)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Send a message on the thread\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PostMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /requests/{id}/tasks/{taskId}/complete:\n    post:\n      tags: [Requests]\n      summary: Complete a customer task (document tasks need `documentId`)\n      parameters:\n        - { $ref: \"#/components/parameters/Id\" }\n        - { name: taskId, in: path, required: true, schema: { type: string, format: uuid } }\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CompleteTaskInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /documents/upload-url:\n    post:\n      tags: [Documents]\n      summary: Get a signed upload URL in the private documents bucket\n      description: |\n        Path layout `{customerId}/{scope}/{uuid}-{fileName}`. Then `PUT` the file bytes to `signedUrl`\n        with the returned headers, then confirm with `POST /documents` (body provided in `confirm.body`).\n        Uploading is not the same as notifying the insurer — the broker delivers documents.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UploadUrlInput\" } } }\n      responses:\n        \"200\":\n          description: Upload target\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          bucket: { type: string }\n                          path: { type: string }\n                          token: { type: string }\n                          signedUrl: { type: string, format: uri }\n                          method: { type: string, enum: [PUT] }\n                          headers: { type: object, additionalProperties: { type: string } }\n                          expiresInSeconds: { type: integer }\n                          confirm: { type: object }\n  /documents:\n    post:\n      tags: [Documents]\n      summary: Confirm an upload and create the document record\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ConfirmUploadInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /documents/{id}/url:\n    get:\n      tags: [Documents]\n      summary: Signed download URL (valid 5 minutes)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { name: download, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /applications:\n    post:\n      tags: [Applications & payments]\n      summary: Apply for a ready-to-accept quote\n      description: Requires the broker disclosure to have been acknowledged and the quote to be `ready_to_accept` and unexpired. Idempotent per quote.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ApplyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /payments:\n    post:\n      tags: [Applications & payments]\n      summary: Start payment for a submitted application\n      description: |\n        Revalidates the quote at checkout. Premiums settle to the insurer's Paystack subaccount.\n        Open `authorizationUrl` in an in-app browser; for a direct MoMo prompt (`momo` given) `authorizationUrl`\n        is null — show `displayText` and poll `GET /payments/{id}`. Pass `callbackUrl` =\n        `https://<host>/api/payments/return` from the app to be redirected to `covva://payments/return`.\n        In test environments without Paystack keys a **sandbox simulator** page is returned instead.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/InitPaymentRequest\" } } }\n      responses:\n        \"201\":\n          description: Payment started\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/InitiatePaymentResult\" } }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n  /payments/{id}:\n    get:\n      tags: [Applications & payments]\n      summary: Poll a payment (re-verifies pending Paystack payments)\n      description: \"`coverActive` is true only when the insurer has issued the policy.\"\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /policies:\n    get:\n      tags: [Policies]\n      summary: Policy wallet\n      parameters: [{ name: status, in: query, schema: { $ref: \"#/components/schemas/PolicyStatus\" } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}:\n    get:\n      tags: [Policies]\n      summary: Policy detail with cover wording, documents, claims and disclosure\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    patch:\n      tags: [Policies]\n      summary: Rename a policy (nickname only)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { type: object, required: [nickname], properties: { nickname: { type: [string, \"null\"], maxLength: 60 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/external:\n    post:\n      tags: [Policies]\n      summary: Add a policy bought elsewhere (shown as \"Added by you\")\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AddExternalPolicyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}/renewal:\n    post:\n      tags: [Policies]\n      summary: Start a renewal review (or a switch review for external policies)\n      description: Existing cover is never cancelled. Renewal prices are estimates until the insurer confirms.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RenewalInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n\n  /claims:\n    get:\n      tags: [Claims]\n      summary: The customer's claims\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Claims]\n      summary: Report a claim to the broker\n      description: \"Reporting is not approval: show `disclaimer`. Returns the evidence checklist (`requiredEvidence`).\"\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ReportClaimInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}:\n    get:\n      tags: [Claims]\n      summary: Claim detail, timeline and documents\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /claims/{id}/withdraw:\n    post:\n      tags: [Claims]\n      summary: Withdraw a claim before the insurer decides\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /complaints:\n    get:\n      tags: [Complaints]\n      summary: The customer's complaints\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Complaints]\n      summary: File a complaint (routed to the broker, insurer or platform; SLA from settings)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/FileComplaintInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n\n  /notifications:\n    get:\n      tags: [Notifications & devices]\n      summary: In-app notifications (with `deepLink` for the app) and unread count\n      parameters: [{ $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }, { name: unread, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n  /notifications/read:\n    post:\n      tags: [Notifications & devices]\n      summary: Mark notifications read\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { type: object, properties: { ids: { type: array, items: { type: string, format: uuid }, maxItems: 200 }, all: { type: boolean } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /devices:\n    post:\n      tags: [Notifications & devices]\n      summary: Register an Expo push token (moves the token to this user if it existed)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RegisterDeviceInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /devices/{token}:\n    delete:\n      tags: [Notifications & devices]\n      summary: Unregister a push token (URL-encode it). Call on sign-out.\n      parameters: [{ name: token, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /ai/assistant:\n    post:\n      tags: [AI]\n      summary: Streaming customer assistant (AI SDK UI message stream)\n      description: |\n        Same handler as `/api/ai/assistant`. Use `useChat` with `DefaultChatTransport({ api, headers: { Authorization }, body: { requestId?, policyId?, threadId? } })`.\n        The response is a Server-Sent Events UI message stream (`x-vercel-ai-ui-message-stream: v1`), not an ApiResult.\n        Response header `x-thread-id` identifies the stored conversation; pass it back as `threadId`.\n        Tools are read-only (policies, request status, quote comparison, glossary, needs assessment, draft message to broker — never sends).\n        Rate limit: 15 burst, ~6/min. 503 `unavailable` when the `ai_assistant` flag is off.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AssistantRequest\" } } }\n      responses:\n        \"200\": { description: UI message stream, content: { text/event-stream: { schema: { type: string } } } }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n\n  /partner/requests:\n    get:\n      tags: [Partner API]\n      summary: Requests routed to the broker, or submitted to the insurer (scope requests:read)\n      security: [{ apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: updatedSince, in: query, schema: { type: string, format: date-time } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/quotes:\n    post:\n      tags: [Partner API]\n      summary: Post a quote for a request (scope quotes:write)\n      description: Brokers quote for appointed insurers on their routed requests; insurers quote only for themselves on requests submitted to them. A `ready_to_accept` quote moves the request to `quotes_ready` and notifies the customer.\n      security: [{ apiKey: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/BrokerQuoteInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/policies/{id}/issue:\n    post:\n      tags: [Partner API]\n      summary: Issue a pending policy — activates cover (insurer keys only, scope policies:issue)\n      description: Requires a confirmed payment. Records `policy_active` usage, completes the request and notifies the customer.\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/IssuePolicyBody\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/status:\n    post:\n      tags: [Partner API]\n      summary: Update a claim's status or decision (insurer keys only, scope claims:write)\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerClaimStatusInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /openapi:\n    get:\n      tags: [System]\n      summary: This document (YAML)\n      security: []\n      responses:\n        \"200\": { description: OpenAPI document, content: { application/yaml: { schema: { type: string } } } }\n\nwebhooks:\n  request.created:\n    post:\n      tags: [Webhooks]\n      summary: A request was routed to the broker of record\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  request.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A request changed status (data.from_status, data.status)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  quote.ready:\n    post:\n      tags: [Webhooks]\n      summary: Quotes were sent to the customer, or a binding quote was posted\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  application.submitted:\n    post:\n      tags: [Webhooks]\n      summary: The customer applied for a quote\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  payment.succeeded:\n    post:\n      tags: [Webhooks]\n      summary: Premium confirmed by the payment provider (policy pending issuance — not active)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  policy.issued:\n    post:\n      tags: [Webhooks]\n      summary: The insurer issued the policy; cover is active\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.reported:\n    post:\n      tags: [Webhooks]\n      summary: A claim was reported (reporting is not approval)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A claim changed status\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  complaint.filed:\n    post:\n      tags: [Webhooks]\n      summary: A complaint owned by your organisation was filed\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  test.ping:\n    post:\n      tags: [Webhooks]\n      summary: Test delivery sent from the settings page\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n\ncomponents:\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\n      bearerFormat: Supabase access token (JWT)\n    apiKey:\n      type: apiKey\n      in: header\n      name: x-api-key\n      description: \"Partner key `imk_<prefix>_<secret>`; the platform stores only sha256(key).\"\n\n  parameters:\n    Id: { name: id, in: path, required: true, schema: { type: string, format: uuid } }\n    Limit: { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 25 } }\n    Before: { name: before, in: query, description: Cursor (ISO timestamp from `nextCursor`), schema: { type: string, format: date-time } }\n\n  responses:\n    Ok:\n      description: Success\n      content: { application/json: { schema: { $ref: \"#/components/schemas/OkEnvelope\" } } }\n    Page:\n      description: A page of items\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      items: { type: array, items: { type: object } }\n                      nextCursor: { type: [string, \"null\"], format: date-time }\n    Error:\n      description: Error\n      content: { application/json: { schema: { $ref: \"#/components/schemas/ErrorEnvelope\" } } }\n    Me:\n      description: Current user\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      profile: { type: object, description: \"profiles row; Ghana Card returned as ghana_card_last4 only\" }\n                      memberships: { type: array, items: { type: object } }\n                      isPartner: { type: boolean }\n                      flags: { type: object, additionalProperties: { type: boolean }, description: \"feature_flags (e.g. demo_mode, ai_assistant)\" }\n                      consents: { type: object, additionalProperties: { type: object } }\n                      versions: { type: object, properties: { terms: { type: [string, \"null\"] }, privacy: { type: [string, \"null\"] } } }\n                      needsConsent: { type: boolean }\n\n  schemas:\n    OkEnvelope:\n      type: object\n      required: [ok, data]\n      properties:\n        ok: { const: true }\n        data: {}\n    ErrorEnvelope:\n      type: object\n      required: [ok, error]\n      properties:\n        ok: { const: false }\n        error:\n          type: object\n          required: [code, message]\n          properties:\n            code: { $ref: \"#/components/schemas/ErrorCode\" }\n            message: { type: string, description: Safe to show to users }\n            details: {}\n    ErrorCode:\n      type: string\n      enum: [unauthorised, forbidden, not_found, invalid_input, business_rule, conflict, rate_limited, unavailable, internal_error]\n\n    RequestStatus:\n      type: string\n      enum: [draft, submitted, awaiting_customer_info, adviser_action, insurer_response, quotes_ready, payment_confirmation, policy_documents, completed, cancelled, closed_no_cover]\n    QuoteStatus:\n      type: string\n      enum: [estimate, awaiting_underwriting, ready_to_accept, accepted, expired, declined, withdrawn]\n    PolicyStatus:\n      type: string\n      enum: [pending_issuance, active, lapsed, cancelled, expired, renewed]\n    ClaimStatus:\n      type: string\n      enum: [draft, reported, delivered_to_insurer, acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed, withdrawn]\n    ComplaintStatus:\n      type: string\n      enum: [open, acknowledged, investigating, resolved, escalated_nic, closed]\n    PaymentStatus:\n      type: string\n      enum: [pending, processing, succeeded, failed, refunded, reversed, abandoned]\n    CategoryAvailability:\n      type: string\n      enum: [integrated, broker_assisted, planned]\n    DocumentKind:\n      type: string\n      enum: [id_document, vehicle_registration, drivers_licence, photo, proof_of_address, medical, policy_schedule, certificate, policy_wording, receipt, endorsement, claim_evidence, police_report, invoice, other]\n    ConsentType:\n      type: string\n      enum: [terms, privacy, marketing, data_sharing_broker, data_sharing_insurer, ai_assistance]\n\n    RiskField:\n      type: object\n      required: [key, label, type]\n      properties:\n        key: { type: string }\n        label: { type: string }\n        type: { type: string, enum: [text, number, currency, select, multiselect, boolean, date, region] }\n        required: { type: boolean }\n        min: { type: number }\n        max: { type: number }\n        placeholder: { type: string }\n        help: { type: string }\n        options: { type: array, items: { type: object, properties: { value: { type: string }, label: { type: string } } } }\n    Category:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        slug: { type: string }\n        name: { type: string }\n        short_description: { type: [string, \"null\"] }\n        icon: { type: [string, \"null\"], description: lucide icon name }\n        segment: { type: string, enum: [personal, business, specialist] }\n        availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        availabilityLabel: { type: string }\n        availabilityPromise: { type: string }\n        risk_schema: { type: array, items: { $ref: \"#/components/schemas/RiskField\" } }\n        required_documents: { type: array, items: { $ref: \"#/components/schemas/DocumentKind\" } }\n        regulatory_note: { type: [string, \"null\"] }\n        default_sla_hours: { type: integer }\n\n    UpdateProfileInput:\n      type: object\n      properties:\n        fullName: { type: string, maxLength: 200 }\n        preferredName: { type: [string, \"null\"] }\n        phone: { type: [string, \"null\"], pattern: \"^\\\\+?\\\\d{9,15}$\" }\n        accountType: { type: string, enum: [individual, business] }\n        businessName: { type: [string, \"null\"] }\n        dateOfBirth: { type: [string, \"null\"], format: date }\n        ghanaCardNumber: { type: [string, \"null\"], pattern: \"^GHA-\\\\d{9}-\\\\d$\" }\n        region: { type: [string, \"null\"] }\n        city: { type: [string, \"null\"] }\n        locale: { type: string }\n        avatarUrl: { type: [string, \"null\"], format: uri }\n        notificationPrefs: { type: object, properties: { email: { type: boolean }, sms: { type: boolean }, push: { type: boolean }, whatsapp: { type: boolean } } }\n        onboarded: { const: true }\n    RecordConsentsInput:\n      type: object\n      required: [consents]\n      properties:\n        consents:\n          type: array\n          minItems: 1\n          maxItems: 10\n          items:\n            type: object\n            required: [type, granted]\n            properties:\n              type: { $ref: \"#/components/schemas/ConsentType\" }\n              granted: { type: boolean }\n              version: { type: string }\n              context: { type: string }\n    NeedsAssessmentInput:\n      type: object\n      required: [answers]\n      properties:\n        answers: { type: object, additionalProperties: { oneOf: [{ type: string }, { type: array, items: { type: string } }, { type: boolean }] } }\n        anonymousId: { type: string }\n    NeedsResult:\n      type: object\n      properties:\n        id: { type: [string, \"null\"], format: uuid }\n        suggestions:\n          type: array\n          items:\n            type: object\n            properties:\n              slug: { type: string }\n              name: { type: string }\n              priority: { type: string, enum: [essential, recommended, consider] }\n              why: { type: string }\n              availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        needsAdviser: { type: boolean }\n        adviserReason: { type: [string, \"null\"] }\n        note: { type: string }\n\n    CreateRequestInput:\n      type: object\n      required: [categorySlug, risk]\n      properties:\n        categorySlug: { type: string }\n        type: { type: string, enum: [new_cover, renewal, switch, endorsement, service], default: new_cover }\n        risk: { type: object, additionalProperties: true, description: \"Answers keyed by the category's risk_schema field keys\" }\n        relatedPolicyId: { type: string, format: uuid }\n        needsAssessmentId: { type: string, format: uuid }\n        submit: { type: boolean, default: true }\n    DisclosureAckInput:\n      type: object\n      properties:\n        stage: { type: string, enum: [before_advice, before_application, broker_change], default: before_application }\n        method: { type: string, enum: [in_app, sms, email, call], default: in_app }\n    PostMessageInput:\n      type: object\n      required: [body]\n      properties:\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, items: { type: object, required: [documentId, name], properties: { documentId: { type: string, format: uuid }, name: { type: string } } } }\n    CompleteTaskInput:\n      type: object\n      properties:\n        documentId: { type: string, format: uuid }\n        note: { type: string, maxLength: 1000 }\n\n    Quote:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        status: { $ref: \"#/components/schemas/QuoteStatus\" }\n        statusLabel: { type: string }\n        statusHint: { type: [string, \"null\"] }\n        is_binding: { type: boolean }\n        premium: { type: number }\n        taxes: { type: number }\n        fees: { type: number }\n        currency: { type: string, example: GHS }\n        billing_period: { type: string }\n        sum_insured: { type: [number, \"null\"] }\n        excess: { type: [number, \"null\"] }\n        coverage: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, included: { type: boolean } } } }\n        limits: { type: object }\n        excesses: { type: object }\n        exclusions: { type: array, items: { type: string } }\n        key_exclusion: { type: [string, \"null\"] }\n        waiting_period_days: { type: integer }\n        optional_benefits: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, premium: { type: number } } } }\n        valid_until: { type: [string, \"null\"], format: date-time }\n        expired: { type: boolean }\n        paid_placement: { type: boolean }\n        commission_disclosure: { type: [string, \"null\"] }\n        labels: { type: array, items: { type: string }, description: \"Explained labels, e.g. Lowest premium\" }\n        demo: { type: boolean }\n        insurer: { type: object, properties: { id: { type: string }, name: { type: string }, slug: { type: string }, logo_url: { type: [string, \"null\"] } } }\n        product: { type: [object, \"null\"], properties: { id: { type: string }, name: { type: string }, tier: { type: [string, \"null\"] } } }\n    QuotesResult:\n      type: object\n      properties:\n        request: { type: object }\n        broker: { type: [object, \"null\"] }\n        quotes: { type: array, items: { $ref: \"#/components/schemas/Quote\" } }\n        comparison:\n          type: object\n          properties:\n            engineVersion: { type: string }\n            insurersCompared: { type: integer }\n            productsCompared: { type: integer }\n            criteria: { type: object }\n            ranked: { type: array, items: { type: object } }\n            paidPlacements: { type: array, items: { type: object } }\n            materialExclusions: { type: array, items: { type: object } }\n            disclaimer: { type: string }\n        summary: { type: string }\n        disclosure: { type: [string, \"null\"] }\n        comparedAt: { type: string, format: date-time }\n        demoMode: { type: boolean }\n        demoDisclaimer: { type: [string, \"null\"] }\n\n    UploadUrlInput:\n      type: object\n      required: [scope, fileName, mimeType, sizeBytes]\n      properties:\n        scope: { type: string, enum: [requests, policies, claims, profile] }\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [application/pdf, image/jpeg, image/png, image/webp, image/heic, application/msword, application/vnd.openxmlformats-officedocument.wordprocessingml.document] }\n        sizeBytes: { type: integer, maximum: 20971520 }\n        kind: { $ref: \"#/components/schemas/DocumentKind\" }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        taskId: { type: string, format: uuid }\n    ConfirmUploadInput:\n      allOf:\n        - $ref: \"#/components/schemas/UploadUrlInput\"\n        - type: object\n          required: [path]\n          properties:\n            path: { type: string }\n            checksum: { type: string }\n\n    ApplyInput:\n      type: object\n      required: [quoteId, declarations, acceptTerms]\n      properties:\n        quoteId: { type: string, format: uuid }\n        declarations: { type: object, additionalProperties: { oneOf: [{ type: boolean }, { type: string }] } }\n        selectedBenefits: { type: array, items: { type: string }, description: optional_benefits keys }\n        acceptTerms: { const: true }\n    InitPaymentRequest:\n      type: object\n      required: [applicationId]\n      properties:\n        applicationId: { type: string, format: uuid }\n        channel: { type: string, enum: [mobile_money, card, bank_transfer], default: mobile_money }\n        callbackUrl: { type: string, format: uri }\n        momo:\n          type: object\n          required: [phone, provider]\n          properties:\n            phone: { type: string, example: \"0244123456\" }\n            provider: { type: string, enum: [mtn, vod, atl] }\n    InitiatePaymentResult:\n      type: object\n      properties:\n        paymentId: { type: string, format: uuid }\n        reference: { type: string }\n        authorizationUrl: { type: [string, \"null\"], format: uri }\n        status: { $ref: \"#/components/schemas/PaymentStatus\" }\n        displayText: { type: [string, \"null\"] }\n\n    WebhookEnvelope:\n      type: object\n      required: [id, event, created_at, attempt, org_id, data]\n      properties:\n        id: { type: string, description: Delivery id (stable across retries — de-duplicate on it) }\n        event: { type: string, enum: [request.created, request.status_changed, quote.ready, application.submitted, payment.succeeded, policy.issued, claim.reported, claim.status_changed, complaint.filed, test.ping] }\n        created_at: { type: string, format: date-time }\n        attempt: { type: integer, minimum: 1, maximum: 5 }\n        org_id: { type: string, format: uuid, description: The organisation the endpoint belongs to }\n        data:\n          type: object\n          additionalProperties: true\n          description: Ids, references, statuses, amounts and dates only. Never personal data.\n          properties:\n            request_id: { type: string, format: uuid }\n            reference: { type: string }\n            status: { type: string }\n            from_status: { type: string }\n            policy_id: { type: string, format: uuid }\n            claim_id: { type: string, format: uuid }\n            complaint_id: { type: string, format: uuid }\n            payment_id: { type: string, format: uuid }\n            application_id: { type: string, format: uuid }\n            quote_id: { type: string, format: uuid }\n    AddExternalPolicyInput:\n      type: object\n      required: [categorySlug, policyNumber, coverStart, coverEnd]\n      description: Give either `insurerOrgId` (an insurer on the platform) or `insurerName` (any other insurer; stored as `external_insurer_name`, no organisation is created).\n      properties:\n        categorySlug: { type: string }\n        insurerOrgId: { type: string, format: uuid, description: From GET /catalog/insurers }\n        insurerName: { type: string, minLength: 2, maxLength: 120, description: Insurer not on the platform, as printed on the policy }\n        policyNumber: { type: string }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n        premium: { type: number }\n        sumInsured: { type: number }\n        nickname: { type: string, maxLength: 60 }\n        documentId: { type: string, format: uuid }\n    RenewalInput:\n      type: object\n      properties:\n        risk: { type: object, additionalProperties: true, description: Defaults to the original request's risk details }\n        changes: { type: string, maxLength: 2000, description: \"What has changed (posted to the broker)\" }\n\n    ReportClaimInput:\n      type: object\n      required: [policyId, incidentType, incidentAt, description]\n      properties:\n        policyId: { type: string, format: uuid }\n        incidentType: { type: string, example: Accident }\n        incidentAt: { type: string, format: date-time }\n        location: { type: string, maxLength: 300 }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        amountClaimed: { type: number }\n    FileComplaintInput:\n      type: object\n      required: [subject, description, category]\n      properties:\n        subject: { type: string, minLength: 3, maxLength: 200 }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        category: { type: string, enum: [advice, service, claims, payment, data_privacy, technology, other] }\n        againstParty: { type: string, enum: [broker, insurer, platform], default: broker }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        desiredOutcome: { type: string, maxLength: 2000 }\n    RegisterDeviceInput:\n      type: object\n      required: [token, platform]\n      properties:\n        token: { type: string, example: \"ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]\" }\n        platform: { type: string, enum: [ios, android, web] }\n        provider: { type: string, enum: [expo, fcm, apns, webpush], default: expo }\n        appVersion: { type: string }\n    AssistantRequest:\n      type: object\n      required: [messages]\n      properties:\n        messages: { type: array, maxItems: 60, items: { type: object, description: \"AI SDK UIMessage { id, role, parts }\" } }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        threadId: { type: string, format: uuid }\n\n    BrokerQuoteInput:\n      type: object\n      required: [requestId, insurerOrgId, status, premium]\n      properties:\n        requestId: { type: string, format: uuid }\n        insurerOrgId: { type: string, format: uuid }\n        productVersionId: { type: string, format: uuid }\n        status: { type: string, enum: [estimate, awaiting_underwriting, ready_to_accept] }\n        premium: { type: number, minimum: 0 }\n        excess: { type: number, minimum: 0 }\n        sumInsured: { type: number, minimum: 0 }\n        keyExclusion: { type: string }\n        validUntil: { type: string, format: date-time, description: Defaults to 14 days for ready_to_accept }\n        brokerNote: { type: string, maxLength: 2000 }\n    IssuePolicyBody:\n      type: object\n      required: [policyNumber, coverStart, coverEnd]\n      properties:\n        policyNumber: { type: string, minLength: 3, maxLength: 60 }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n    PartnerClaimStatusInput:\n      type: object\n      required: [status]\n      properties:\n        status: { type: string, enum: [acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed] }\n        note: { type: string, maxLength: 2000 }\n        insurerReference: { type: string }\n        decisionAmount: { type: number, minimum: 0 }\n        visibleToCustomer: { type: boolean, default: true }\n";
